package com.carebridge.backend.integration;
import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.when;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.carebridge.backend.common.config.JpaAuditingConfig;import com.carebridge.backend.config.MockMvcSecurityBuilderConfig;import com.carebridge.backend.partner.controller.PartnerApprovalController;import com.carebridge.backend.partner.dto.response.PartnerDecisionResponse;import com.carebridge.backend.partner.entity.OrganizationStatus;import com.carebridge.backend.partner.service.PartnerApprovalService;import com.carebridge.backend.security.config.SecurityConfig;import com.carebridge.backend.security.jwt.JwtTokenProvider;import com.carebridge.backend.security.repository.UserRepository;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.*;import org.springframework.http.MediaType;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
@WebMvcTest(value=PartnerApprovalController.class,excludeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes=JpaAuditingConfig.class))@Import({SecurityConfig.class,MockMvcSecurityBuilderConfig.class})class PartnerApprovalIntegrationTest{static final UUID ADMIN=UUID.fromString("fc000000-0000-0000-0000-0000000000ad"),PARTNER=UUID.fromString("fd000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@MockitoBean PartnerApprovalService service;@MockitoBean JwtTokenProvider jwt;@MockitoBean UserRepository users;@Test @WithMockUser(username="fc000000-0000-0000-0000-0000000000ad",roles="SYSTEM_ADMIN")void appTcInt001_fullPostReturnsTransition()throws Exception{when(service.decide(eq(PARTNER),any(),eq(ADMIN))).thenReturn(new PartnerDecisionResponse(PARTNER,OrganizationStatus.PENDING_APPROVAL,OrganizationStatus.APPROVED,ADMIN,null,Instant.now()));mvc.perform(post("/api/v1/admin/partners/"+PARTNER+"/decision").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"decision\":\"APPROVE\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.newStatus").value("APPROVED"));}}
